cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://backend:4000/api/v1/swagger/swagger-ui-init.js");
  const txt = await r.text();
  const start = txt.indexOf("\"paths\"");
  const seg = txt.slice(start, start + 200000);
  const re = /"(\/api\/v1\/(school|teacher|class|department|student)[^"]*)"/g;
  const set = new Set();
  let m;
  while ((m = re.exec(seg)) !== null) set.add(m[1]);
  console.log([...set].sort().join("\n"));
})();
' 2>&1 | head -50
